insert into public.exercicios (nome, instrucoes, series_padrao, reps_padrao, fotos, ativo) select 'Ponte unilateral', 'Deite de barriga para cima com um pé apoiado e a outra perna esticada, na altura do outro joelho. Suba o quadril empurrando o chão com o pé apoiado até alinhar joelho, quadril e ombro, e desça devagar. Cuidado: o quadril não pode cair para o lado da perna esticada.', 3, '8 por lado', array['fotos-exercicios/desenho-ponte-unilateral-1.webp','fotos-exercicios/desenho-ponte-unilateral-2.webp']::text[], true where not exists (select 1 from public.exercicios where nome = 'Ponte unilateral');
insert into public.exercicios (nome, instrucoes, series_padrao, reps_padrao, fotos, ativo) select 'Ponte com marcha', 'Suba o quadril na ponte e mantenha. Tire um pé do chão levando o joelho em direção ao peito, volte e troque, como uma marcha lenta. Cuidado: o quadril fica parado e nivelado durante a troca.', 2, '6 por lado', array['fotos-exercicios/desenho-ponte-marcha-1.webp','fotos-exercicios/desenho-ponte-marcha-2.webp']::text[], true where not exists (select 1 from public.exercicios where nome = 'Ponte com marcha');
insert into public.exercicios (nome, instrucoes, series_padrao, reps_padrao, fotos, ativo) select 'Ponte com bola entre os joelhos', 'Deitado com os joelhos dobrados e uma bola ou almofada entre eles. Aperte a bola e suba o quadril até alinhar joelho, quadril e ombro. Desça devagar sem soltar a bola. Cuidado: não arqueie a lombar no alto.', 3, '10', array['fotos-exercicios/desenho-ponte-bola-1.webp','fotos-exercicios/desenho-ponte-bola-2.webp']::text[], true where not exists (select 1 from public.exercicios where nome = 'Ponte com bola entre os joelhos');
insert into public.exercicios (nome, instrucoes, series_padrao, reps_padrao, fotos, ativo) select 'Prancha frontal', 'Apoie os antebraços no chão, cotovelos abaixo dos ombros. Estique as pernas apoiando a ponta dos pés e mantenha o corpo reto, da cabeça aos calcanhares. Cuidado: não deixe o quadril cair nem subir demais; respire normalmente.', 3, '20 a 30 s', array['fotos-exercicios/desenho-prancha-frontal-1.webp','fotos-exercicios/desenho-prancha-frontal-2.webp']::text[], true where not exists (select 1 from public.exercicios where nome = 'Prancha frontal');
insert into public.exercicios (nome, instrucoes, series_padrao, reps_padrao, fotos, ativo) select 'Prancha lateral com joelhos apoiados', 'Deite de lado apoiado no antebraço, cotovelo abaixo do ombro e joelhos dobrados. Suba o quadril até alinhar ombro, quadril e joelhos e segure. Cuidado: o quadril não pode cair; o pescoço fica alinhado.', 3, '15 a 20 s por lado', array['fotos-exercicios/desenho-prancha-lateral-joelhos-1.webp','fotos-exercicios/desenho-prancha-lateral-joelhos-2.webp']::text[], true where not exists (select 1 from public.exercicios where nome = 'Prancha lateral com joelhos apoiados');
insert into public.exercicios (nome, instrucoes, series_padrao, reps_padrao, fotos, ativo) select 'Prancha alta (braços estendidos)', 'Comece em quatro apoios, mãos abaixo dos ombros. Estique uma perna de cada vez para trás, apoiando a ponta dos pés, e mantenha o corpo reto. Cuidado: abdômen firme, sem afundar a lombar.', 3, '20 s', array['fotos-exercicios/desenho-prancha-alta-1.webp','fotos-exercicios/desenho-prancha-alta-2.webp']::text[], true where not exists (select 1 from public.exercicios where nome = 'Prancha alta (braços estendidos)');
insert into public.exercicios (nome, instrucoes, series_padrao, reps_padrao, fotos, ativo) select 'Marcha deitada (pernas alternadas)', 'Deitado com os joelhos dobrados, encoste levemente a lombar no chão. Tire um pé do chão até o joelho ficar acima do quadril, volte devagar e troque. Cuidado: a lombar não pode desgrudar do chão.', 2, '8 por lado', array['fotos-exercicios/desenho-marcha-deitada-1.webp','fotos-exercicios/desenho-marcha-deitada-2.webp']::text[], true where not exists (select 1 from public.exercicios where nome = 'Marcha deitada (pernas alternadas)');
insert into public.exercicios (nome, instrucoes, series_padrao, reps_padrao, fotos, ativo) select 'Deslizar o calcanhar deitado', 'Deitado com os joelhos dobrados, deslize um calcanhar pelo chão até esticar a perna e volte, mantendo o abdômen firme. Troque de lado. Cuidado: a pelve não pode balançar.', 2, '10 por lado', array['fotos-exercicios/desenho-deslizar-calcanhar-1.webp','fotos-exercicios/desenho-deslizar-calcanhar-2.webp']::text[], true where not exists (select 1 from public.exercicios where nome = 'Deslizar o calcanhar deitado');
insert into public.exercicios (nome, instrucoes, series_padrao, reps_padrao, fotos, ativo) select 'Curl-up de McGill', 'Deite com uma perna esticada e a outra dobrada, mãos sob a lombar. Tire só a cabeça e os ombros do chão, segure de 5 a 8 segundos e desça. Cuidado: o pescoço acompanha o tronco, sem puxar o queixo ao peito.', 3, '6 (segure 8 s)', array['fotos-exercicios/desenho-curl-up-mcgill-1.webp','fotos-exercicios/desenho-curl-up-mcgill-2.webp']::text[], true where not exists (select 1 from public.exercicios where nome = 'Curl-up de McGill');
insert into public.exercicios (nome, instrucoes, series_padrao, reps_padrao, fotos, ativo) select 'Elevação de perna estendida deitado', 'Deitado com uma perna dobrada e a outra esticada. Contraia a coxa da perna esticada e suba até a altura do outro joelho; desça devagar. Cuidado: a lombar fica apoiada no chão.', 3, '10 por lado', array['fotos-exercicios/desenho-elevacao-perna-estendida-1.webp','fotos-exercicios/desenho-elevacao-perna-estendida-2.webp']::text[], true where not exists (select 1 from public.exercicios where nome = 'Elevação de perna estendida deitado');
insert into public.exercicios (nome, instrucoes, series_padrao, reps_padrao, fotos, ativo) select 'Joelhos ao peito (as duas pernas)', 'Deitado de barriga para cima, abrace os dois joelhos e traga em direção ao peito, respirando devagar. Solte aos poucos. Cuidado: puxe só até sentir alongar a lombar, sem dor.', 2, '20 s', array['fotos-exercicios/desenho-joelhos-ao-peito-1.webp','fotos-exercicios/desenho-joelhos-ao-peito-2.webp']::text[], true where not exists (select 1 from public.exercicios where nome = 'Joelhos ao peito (as duas pernas)');
insert into public.exercicios (nome, instrucoes, series_padrao, reps_padrao, fotos, ativo) select 'Superman alternado de bruços', 'Deite de bruços com os braços esticados à frente. Suba juntos um braço e a perna oposta, poucos centímetros, segure 2 segundos e troque. Cuidado: olhe para o chão e não force a lombar.', 2, '8 por lado', array['fotos-exercicios/desenho-superman-alternado-1.webp','fotos-exercicios/desenho-superman-alternado-2.webp']::text[], true where not exists (select 1 from public.exercicios where nome = 'Superman alternado de bruços');
insert into public.exercicios (nome, instrucoes, series_padrao, reps_padrao, fotos, ativo) select 'Extensão de bruços com apoio das mãos (McKenzie)', 'Deite de bruços com as mãos no chão, na altura dos ombros. Estique os cotovelos subindo o tronco e deixe o quadril e a barriga apoiados no chão. Desça devagar. Cuidado: se a dor descer para a perna, pare.', 1, '10', array['fotos-exercicios/desenho-mckenzie-1.webp','fotos-exercicios/desenho-mckenzie-2.webp']::text[], true where not exists (select 1 from public.exercicios where nome = 'Extensão de bruços com apoio das mãos (McKenzie)');
insert into public.exercicios (nome, instrucoes, series_padrao, reps_padrao, fotos, ativo) select 'Balanço para trás em quatro apoios', 'Em quatro apoios, leve o quadril para trás em direção aos calcanhares, mantendo as mãos no lugar, e volte. Movimento lento, acompanhando a respiração. Cuidado: vá só até onde a lombar ficar confortável.', 2, '10', array['fotos-exercicios/desenho-balanco-quatro-apoios-1.webp','fotos-exercicios/desenho-balanco-quatro-apoios-2.webp']::text[], true where not exists (select 1 from public.exercicios where nome = 'Balanço para trás em quatro apoios');
insert into public.exercicios (nome, instrucoes, series_padrao, reps_padrao, fotos, ativo) select 'Push-up plus em quatro apoios', 'Em quatro apoios com os braços esticados. Deixe o peito afundar entre os ombros e depois empurre o chão, afastando as escápulas e arredondando levemente a parte alta das costas. Cuidado: cotovelos sempre esticados.', 2, '12', array['fotos-exercicios/desenho-push-up-plus-1.webp','fotos-exercicios/desenho-push-up-plus-2.webp']::text[], true where not exists (select 1 from public.exercicios where nome = 'Push-up plus em quatro apoios');
insert into public.exercicios (nome, instrucoes, series_padrao, reps_padrao, fotos, ativo) select 'Flexão de braço na parede', 'Em pé, de frente para a parede e a um passo dela. Apoie as mãos na parede na altura dos ombros e dobre os cotovelos aproximando o peito; depois empurre de volta. Cuidado: corpo reto, sem empinar o bumbum.', 3, '10', array['fotos-exercicios/desenho-flexao-parede-1.webp','fotos-exercicios/desenho-flexao-parede-2.webp']::text[], true where not exists (select 1 from public.exercicios where nome = 'Flexão de braço na parede');
insert into public.exercicios (nome, instrucoes, series_padrao, reps_padrao, fotos, ativo) select 'Agachamento na parede', 'Encoste as costas na parede e afaste os pés à frente. Deslize para baixo até os joelhos ficarem dobrados, no máximo a 90 graus, e segure. Cuidado: joelhos alinhados com a ponta dos pés.', 3, '20 a 30 s', array['fotos-exercicios/desenho-agachamento-parede-1.webp','fotos-exercicios/desenho-agachamento-parede-2.webp']::text[], true where not exists (select 1 from public.exercicios where nome = 'Agachamento na parede');
insert into public.exercicios (nome, instrucoes, series_padrao, reps_padrao, fotos, ativo) select 'Agachamento com apoio na cadeira', 'Fique em pé atrás de uma cadeira, segurando o encosto. Sente para trás como se fosse sentar, com o peso nos calcanhares, e suba. Cuidado: os joelhos não passam muito da ponta dos pés.', 3, '10', array['fotos-exercicios/desenho-agachamento-cadeira-1.webp','fotos-exercicios/desenho-agachamento-cadeira-2.webp']::text[], true where not exists (select 1 from public.exercicios where nome = 'Agachamento com apoio na cadeira');
insert into public.exercicios (nome, instrucoes, series_padrao, reps_padrao, fotos, ativo) select 'Dobradiça de quadril com cabo de vassoura', 'Em pé, segure um cabo de vassoura nas costas, encostado na cabeça, entre as escápulas e no bumbum. Leve o quadril para trás inclinando o tronco, sem o cabo desencostar, e volte. Cuidado: os joelhos dobram só um pouco.', 3, '10', array['fotos-exercicios/desenho-dobradica-vassoura-1.webp','fotos-exercicios/desenho-dobradica-vassoura-2.webp']::text[], true where not exists (select 1 from public.exercicios where nome = 'Dobradiça de quadril com cabo de vassoura');
insert into public.exercicios (nome, instrucoes, series_padrao, reps_padrao, fotos, ativo) select 'Subida no degrau', 'De frente para um degrau, apoie um pé inteiro nele. Suba empurrando com a perna da frente até ficar em pé no degrau e desça devagar com a mesma perna. Cuidado: use um corrimão ou parede para se apoiar.', 2, '8 por lado', array['fotos-exercicios/desenho-subida-degrau-1.webp','fotos-exercicios/desenho-subida-degrau-2.webp']::text[], true where not exists (select 1 from public.exercicios where nome = 'Subida no degrau');
insert into public.exercicios (nome, instrucoes, series_padrao, reps_padrao, fotos, ativo) select 'Elevação de panturrilha em pé', 'Em pé, segurando numa parede, suba na ponta dos pés devagar, segure 1 segundo e desça controlando. Cuidado: o peso fica no meio do pé, sem tombar para fora.', 3, '15', array['fotos-exercicios/desenho-panturrilha-1.webp','fotos-exercicios/desenho-panturrilha-2.webp']::text[], true where not exists (select 1 from public.exercicios where nome = 'Elevação de panturrilha em pé');
insert into public.exercicios (nome, instrucoes, series_padrao, reps_padrao, fotos, ativo) select 'Equilíbrio em uma perna', 'Em pé, perto de uma parede para segurança, tire um pé do chão e mantenha o equilíbrio. Troque a perna. Cuidado: olhe para um ponto fixo à frente e mantenha o tronco reto.', 3, '30 s por lado', array['fotos-exercicios/desenho-equilibrio-uma-perna-1.webp','fotos-exercicios/desenho-equilibrio-uma-perna-2.webp']::text[], true where not exists (select 1 from public.exercicios where nome = 'Equilíbrio em uma perna');
insert into public.exercicios (nome, instrucoes, series_padrao, reps_padrao, fotos, ativo) select 'Abdução de quadril em pé', 'Em pé, segurando numa cadeira ou parede, leve uma perna esticada para o lado e volte devagar, sem inclinar o tronco. Cuidado: a ponta do pé aponta para a frente.', 2, '12 por lado', array['fotos-exercicios/desenho-abducao-em-pe-1.webp','fotos-exercicios/desenho-abducao-em-pe-2.webp']::text[], true where not exists (select 1 from public.exercicios where nome = 'Abdução de quadril em pé');
insert into public.exercicios (nome, instrucoes, series_padrao, reps_padrao, fotos, ativo) select 'Extensão de quadril em pé', 'Em pé, de frente para uma cadeira, segurando o encosto. Leve uma perna esticada para trás contraindo o bumbum e volte. Cuidado: não incline o tronco nem arqueie a lombar.', 2, '12 por lado', array['fotos-exercicios/desenho-extensao-quadril-em-pe-1.webp','fotos-exercicios/desenho-extensao-quadril-em-pe-2.webp']::text[], true where not exists (select 1 from public.exercicios where nome = 'Extensão de quadril em pé');
insert into public.exercicios (nome, instrucoes, series_padrao, reps_padrao, fotos, ativo) select 'Marcha estacionária', 'Em pé, marche no lugar levantando os joelhos até uma altura confortável e balançando os braços. Cuidado: tronco reto e respiração tranquila.', 2, '1 min', array['fotos-exercicios/desenho-marcha-estacionaria-1.webp','fotos-exercicios/desenho-marcha-estacionaria-2.webp']::text[], true where not exists (select 1 from public.exercicios where nome = 'Marcha estacionária');
insert into public.exercicios (nome, instrucoes, series_padrao, reps_padrao, fotos, ativo) select 'Inclinação pélvica em pé na parede', 'Encoste as costas na parede com os joelhos levemente dobrados. Encaixe o quadril encostando a lombar na parede e depois solte. Cuidado: movimento pequeno, sem tirar a cabeça da parede.', 2, '10', array['fotos-exercicios/desenho-bascula-parede-1.webp','fotos-exercicios/desenho-bascula-parede-2.webp']::text[], true where not exists (select 1 from public.exercicios where nome = 'Inclinação pélvica em pé na parede');
insert into public.exercicios (nome, instrucoes, series_padrao, reps_padrao, fotos, ativo) select 'Inclinação pélvica sentado', 'Sentado na ponta da cadeira, pés apoiados. Role a pelve para trás arredondando a lombar e depois para a frente, endireitando a coluna. Cuidado: movimento lento, sem dor.', 2, '10', array['fotos-exercicios/desenho-bascula-sentado-1.webp','fotos-exercicios/desenho-bascula-sentado-2.webp']::text[], true where not exists (select 1 from public.exercicios where nome = 'Inclinação pélvica sentado');
insert into public.exercicios (nome, instrucoes, series_padrao, reps_padrao, fotos, ativo) select 'Alongamento de quadríceps em pé', 'Em pé, apoiado numa parede, dobre um joelho e segure o tornozelo atrás, levando o calcanhar em direção ao bumbum. Segure e troque. Cuidado: joelhos lado a lado, sem arquear a lombar.', 2, '30 s por lado', array['fotos-exercicios/desenho-quadriceps-em-pe-1.webp','fotos-exercicios/desenho-quadriceps-em-pe-2.webp']::text[], true where not exists (select 1 from public.exercicios where nome = 'Alongamento de quadríceps em pé');
insert into public.exercicios (nome, instrucoes, series_padrao, reps_padrao, fotos, ativo) select 'Alongamento de quadríceps de bruços', 'Deite de bruços, dobre um joelho e passe uma toalha pelo pé, puxando o calcanhar em direção ao bumbum. Cuidado: quadril apoiado no chão, sem arquear a lombar.', 2, '30 s por lado', array['fotos-exercicios/desenho-quadriceps-brucos-1.webp','fotos-exercicios/desenho-quadriceps-brucos-2.webp']::text[], true where not exists (select 1 from public.exercicios where nome = 'Alongamento de quadríceps de bruços');
insert into public.exercicios (nome, instrucoes, series_padrao, reps_padrao, fotos, ativo) select 'Alongamento de panturrilha na parede', 'De frente para a parede, com as mãos apoiadas. Leve uma perna para trás com o calcanhar no chão e dobre a perna da frente até sentir alongar a panturrilha de trás. Cuidado: o pé de trás aponta para a frente.', 2, '30 s por lado', array['fotos-exercicios/desenho-panturrilha-parede-1.webp','fotos-exercicios/desenho-panturrilha-parede-2.webp']::text[], true where not exists (select 1 from public.exercicios where nome = 'Alongamento de panturrilha na parede');
insert into public.exercicios (nome, instrucoes, series_padrao, reps_padrao, fotos, ativo) select 'Alongamento de adutores sentado (borboleta)', 'Sentado no chão, junte as solas dos pés e deixe os joelhos caírem para os lados. Segure os tornozelos e incline o tronco levemente à frente, com a coluna reta. Cuidado: não force os joelhos para baixo com as mãos.', 2, '30 s', array['fotos-exercicios/desenho-borboleta-1.webp','fotos-exercicios/desenho-borboleta-2.webp']::text[], true where not exists (select 1 from public.exercicios where nome = 'Alongamento de adutores sentado (borboleta)');
insert into public.exercicios (nome, instrucoes, series_padrao, reps_padrao, fotos, ativo) select 'Alongamento de posterior de coxa sentado', 'Sentado no chão com as pernas esticadas, incline o tronco à frente com a coluna reta, levando as mãos em direção aos pés. Cuidado: vá até sentir alongar atrás da coxa, sem forçar.', 2, '30 s', array['fotos-exercicios/desenho-posterior-sentado-1.webp','fotos-exercicios/desenho-posterior-sentado-2.webp']::text[], true where not exists (select 1 from public.exercicios where nome = 'Alongamento de posterior de coxa sentado');
insert into public.exercicios (nome, instrucoes, series_padrao, reps_padrao, fotos, ativo) select 'Alongamento de glúteo sentado na cadeira', 'Sentado, cruze o tornozelo sobre o joelho oposto. Incline o tronco à frente com a coluna reta até sentir alongar o glúteo. Cuidado: não force o joelho para baixo.', 2, '30 s por lado', array['fotos-exercicios/desenho-gluteo-cadeira-1.webp','fotos-exercicios/desenho-gluteo-cadeira-2.webp']::text[], true where not exists (select 1 from public.exercicios where nome = 'Alongamento de glúteo sentado na cadeira');
insert into public.exercicios (nome, instrucoes, series_padrao, reps_padrao, fotos, ativo) select 'Alongamento de posterior em pé com o pé no degrau', 'Em pé, apoie o calcanhar num degrau baixo com a perna esticada. Incline o tronco à frente com a coluna reta até sentir alongar atrás da coxa. Cuidado: ponta do pé para cima e coluna sem arredondar.', 2, '30 s por lado', array['fotos-exercicios/desenho-posterior-degrau-1.webp','fotos-exercicios/desenho-posterior-degrau-2.webp']::text[], true where not exists (select 1 from public.exercicios where nome = 'Alongamento de posterior em pé com o pé no degrau');
insert into public.exercicios (nome, instrucoes, series_padrao, reps_padrao, fotos, ativo) select 'Deslizamento do nervo ciático deitado', 'Deitado, segure atrás da coxa com o quadril dobrado a 90 graus. Estique o joelho devagar puxando a ponta do pé para você e volte. Movimento suave, sem alongar forte. Cuidado: pare se aparecer formigamento que não passa.', 2, '10', array['fotos-exercicios/desenho-ciatico-deitado-1.webp','fotos-exercicios/desenho-ciatico-deitado-2.webp']::text[], true where not exists (select 1 from public.exercicios where nome = 'Deslizamento do nervo ciático deitado');
insert into public.exercicios (nome, instrucoes, series_padrao, reps_padrao, fotos, ativo) select 'Extensão torácica na cadeira', 'Sentado numa cadeira de encosto baixo, mãos atrás da cabeça. Incline a parte alta das costas para trás sobre o encosto, olhando para o teto, e volte. Cuidado: a lombar fica apoiada; o movimento é no meio das costas.', 2, '10', array['fotos-exercicios/desenho-extensao-toracica-cadeira-1.webp','fotos-exercicios/desenho-extensao-toracica-cadeira-2.webp']::text[], true where not exists (select 1 from public.exercicios where nome = 'Extensão torácica na cadeira');
insert into public.exercicios (nome, instrucoes, series_padrao, reps_padrao, fotos, ativo) select 'Extensão torácica deitado com toalha enrolada', 'Deite com uma toalha enrolada atravessada no meio das costas e os joelhos dobrados. Leve os braços acima da cabeça e respire fundo, deixando as costas se abrirem sobre a toalha. Cuidado: apoie a cabeça; não deve doer.', 2, '1 min', array['fotos-exercicios/desenho-extensao-toracica-toalha-1.webp','fotos-exercicios/desenho-extensao-toracica-toalha-2.webp']::text[], true where not exists (select 1 from public.exercicios where nome = 'Extensão torácica deitado com toalha enrolada');
insert into public.exercicios (nome, instrucoes, series_padrao, reps_padrao, fotos, ativo) select 'Retração escapular sentado', 'Sentado com a coluna alta, cotovelos dobrados ao lado do corpo. Leve os cotovelos para trás aproximando as escápulas, segure 3 segundos e solte. Cuidado: não suba os ombros em direção às orelhas.', 2, '12 (segure 3 s)', array['fotos-exercicios/desenho-retracao-escapular-sentado-1.webp','fotos-exercicios/desenho-retracao-escapular-sentado-2.webp']::text[], true where not exists (select 1 from public.exercicios where nome = 'Retração escapular sentado');
insert into public.exercicios (nome, instrucoes, series_padrao, reps_padrao, fotos, ativo) select 'Encolher e soltar os ombros', 'Sentado ou em pé, suba os ombros em direção às orelhas, segure 2 segundos e solte bem devagar, deixando os ombros caírem. Cuidado: puxe o ar ao subir e solte ao descer.', 2, '10', array['fotos-exercicios/desenho-encolher-ombros-1.webp','fotos-exercicios/desenho-encolher-ombros-2.webp']::text[], true where not exists (select 1 from public.exercicios where nome = 'Encolher e soltar os ombros');
insert into public.exercicios (nome, instrucoes, series_padrao, reps_padrao, fotos, ativo) select 'Rotação externa de ombro deitado de lado', 'Deite de lado com o cotovelo de cima dobrado a 90 graus e apoiado na cintura (uma toalha dobrada ajuda). Gire o antebraço para cima, sem tirar o cotovelo do corpo, e volte devagar. Cuidado: movimento lento e sem dor.', 2, '12 por lado', array['fotos-exercicios/desenho-rotacao-externa-lado-1.webp','fotos-exercicios/desenho-rotacao-externa-lado-2.webp']::text[], true where not exists (select 1 from public.exercicios where nome = 'Rotação externa de ombro deitado de lado');
insert into public.exercicios (nome, instrucoes, series_padrao, reps_padrao, fotos, ativo) select 'Abertura de peito com mãos entrelaçadas atrás', 'Em pé, entrelace as mãos atrás do corpo. Estique os braços e afaste-os do corpo, abrindo o peito e aproximando as escápulas. Cuidado: queixo levemente recolhido, sem projetar a cabeça.', 2, '20 s', array['fotos-exercicios/desenho-abertura-peito-1.webp','fotos-exercicios/desenho-abertura-peito-2.webp']::text[], true where not exists (select 1 from public.exercicios where nome = 'Abertura de peito com mãos entrelaçadas atrás');
insert into public.exercicios (nome, instrucoes, series_padrao, reps_padrao, fotos, ativo) select 'Alongamento de tríceps e dorsal com braço acima', 'Em pé, leve um braço acima da cabeça e dobre o cotovelo, com a mão atrás da cabeça. Com a outra mão, puxe o cotovelo e incline levemente o tronco para o lado. Cuidado: não force; respire tranquilo.', 2, '30 s por lado', array['fotos-exercicios/desenho-triceps-dorsal-1.webp','fotos-exercicios/desenho-triceps-dorsal-2.webp']::text[], true where not exists (select 1 from public.exercicios where nome = 'Alongamento de tríceps e dorsal com braço acima');
insert into public.exercicios (nome, instrucoes, series_padrao, reps_padrao, fotos, ativo) select 'Elevação de braços com bastão deitado', 'Deitado com os joelhos dobrados, segure um cabo de vassoura com as duas mãos acima do peito. Leve os braços esticados para trás da cabeça até onde for confortável e volte. Cuidado: as costelas não sobem e a lombar fica apoiada.', 2, '10', array['fotos-exercicios/desenho-bastao-deitado-1.webp','fotos-exercicios/desenho-bastao-deitado-2.webp']::text[], true where not exists (select 1 from public.exercicios where nome = 'Elevação de braços com bastão deitado');
insert into public.exercicios (nome, instrucoes, series_padrao, reps_padrao, fotos, ativo) select 'Flexão lateral cervical ativa', 'Sentado com a coluna alta, incline a cabeça levando a orelha em direção ao ombro, sem subir o ombro. Volte ao centro e troque de lado. Cuidado: movimento suave, só até sentir alongar.', 1, '8 por lado', array['fotos-exercicios/desenho-flexao-lateral-cervical-1.webp','fotos-exercicios/desenho-flexao-lateral-cervical-2.webp']::text[], true where not exists (select 1 from public.exercicios where nome = 'Flexão lateral cervical ativa');
insert into public.exercicios (nome, instrucoes, series_padrao, reps_padrao, fotos, ativo) select 'Rotação cervical ativa', 'Sentado com a coluna alta, gire a cabeça devagar olhando por cima do ombro, volte ao centro e gire para o outro lado. Cuidado: o queixo fica na mesma altura, sem inclinar a cabeça.', 1, '8 por lado', array['fotos-exercicios/desenho-rotacao-cervical-1.webp','fotos-exercicios/desenho-rotacao-cervical-2.webp']::text[], true where not exists (select 1 from public.exercicios where nome = 'Rotação cervical ativa');
insert into public.exercicios (nome, instrucoes, series_padrao, reps_padrao, fotos, ativo) select 'Alongamento do levantador da escápula', 'Sentado, segure o assento com uma mão. Vire o rosto para o lado oposto e olhe em direção à axila, levando o queixo para baixo; com a outra mão sobre a cabeça, aumente o alongamento de leve. Cuidado: sem dor e sem puxar forte.', 2, '30 s por lado', array['fotos-exercicios/desenho-levantador-escapula-1.webp','fotos-exercicios/desenho-levantador-escapula-2.webp']::text[], true where not exists (select 1 from public.exercicios where nome = 'Alongamento do levantador da escápula');
insert into public.exercicios (nome, instrucoes, series_padrao, reps_padrao, fotos, ativo) select 'Isometria cervical com a mão na testa', 'Sentado com a coluna alta, apoie a mão na testa e empurre a cabeça contra a mão, sem deixar a cabeça se mover. Segure 5 segundos e solte. Cuidado: força leve, respirando normalmente.', 2, '5 (segure 5 s)', array['fotos-exercicios/desenho-isometria-cervical-1.webp','fotos-exercicios/desenho-isometria-cervical-2.webp']::text[], true where not exists (select 1 from public.exercicios where nome = 'Isometria cervical com a mão na testa');
insert into public.exercicios (nome, instrucoes, series_padrao, reps_padrao, fotos, ativo) select 'Aceno de cabeça deitado (flexão cervical profunda)', 'Deitado com os joelhos dobrados e a cabeça apoiada. Faça um "sim" bem pequeno, levando o queixo em direção ao pescoço sem tirar a cabeça do apoio, e segure 5 segundos. Cuidado: o movimento é pequeno; não levante a cabeça.', 2, '8 (segure 5 s)', array['fotos-exercicios/desenho-aceno-cabeca-1.webp','fotos-exercicios/desenho-aceno-cabeca-2.webp']::text[], true where not exists (select 1 from public.exercicios where nome = 'Aceno de cabeça deitado (flexão cervical profunda)');
insert into public.exercicios (nome, instrucoes, series_padrao, reps_padrao, fotos, ativo) select 'Respiração costal com mãos nas costelas', 'Sentado, apoie as mãos nas laterais das costelas. Puxe o ar pelo nariz abrindo as costelas contra as mãos e solte o ar devagar pela boca. Cuidado: os ombros não sobem.', 2, '8 respirações', array['fotos-exercicios/desenho-respiracao-costal-1.webp','fotos-exercicios/desenho-respiracao-costal-2.webp']::text[], true where not exists (select 1 from public.exercicios where nome = 'Respiração costal com mãos nas costelas');
insert into public.exercicios (nome, instrucoes, series_padrao, reps_padrao, fotos, ativo) select 'Alongamento lateral de tronco sentado', 'Sentado, leve um braço acima da cabeça e incline o tronco para o lado oposto, sem tirar o quadril da cadeira. Volte e troque. Cuidado: sem girar o tronco; respire fundo.', 2, '20 s por lado', array['fotos-exercicios/desenho-lateral-tronco-sentado-1.webp','fotos-exercicios/desenho-lateral-tronco-sentado-2.webp']::text[], true where not exists (select 1 from public.exercicios where nome = 'Alongamento lateral de tronco sentado');
insert into public.exercicios (nome, instrucoes, series_padrao, reps_padrao, fotos, ativo) select 'Marcha sentada', 'Sentado na ponta da cadeira, coluna alta e mãos apoiadas no assento. Levante um joelho alguns centímetros, como numa marcha, desça devagar e troque. Cuidado: o tronco não pode inclinar para trás.', 2, '10 por lado', array['fotos-exercicios/desenho-marcha-sentada-1.webp','fotos-exercicios/desenho-marcha-sentada-2.webp']::text[], true where not exists (select 1 from public.exercicios where nome = 'Marcha sentada');
insert into public.exercicios (nome, instrucoes, series_padrao, reps_padrao, fotos, ativo) select 'Elevação de braço em quatro apoios', 'Em quatro apoios, estique um braço à frente até a altura do ombro, segure 2 segundos e volte. Troque de lado. Cuidado: tronco parado, sem girar.', 2, '8 por lado', array['fotos-exercicios/desenho-elevacao-braco-quatro-apoios-1.webp','fotos-exercicios/desenho-elevacao-braco-quatro-apoios-2.webp']::text[], true where not exists (select 1 from public.exercicios where nome = 'Elevação de braço em quatro apoios');
insert into public.exercicios (nome, instrucoes, series_padrao, reps_padrao, fotos, ativo) select 'Afundo lateral', 'Em pé, com as pernas bem afastadas. Leve o quadril para um lado dobrando aquele joelho e mantendo a outra perna esticada; volte ao centro e troque. Cuidado: o joelho dobrado aponta na direção da ponta do pé.', 2, '8 por lado', array['fotos-exercicios/desenho-afundo-lateral-1.webp','fotos-exercicios/desenho-afundo-lateral-2.webp']::text[], true where not exists (select 1 from public.exercicios where nome = 'Afundo lateral');
insert into public.exercicios (nome, instrucoes, series_padrao, reps_padrao, fotos, ativo) select 'Agachamento com pernas afastadas (sumô)', 'Em pé, com os pés mais afastados que os ombros e as pontas viradas para fora. Agache levando os joelhos na direção das pontas dos pés e suba. Cuidado: coluna reta e joelhos sem cair para dentro.', 3, '12', array['fotos-exercicios/desenho-agachamento-sumo-1.webp','fotos-exercicios/desenho-agachamento-sumo-2.webp']::text[], true where not exists (select 1 from public.exercicios where nome = 'Agachamento com pernas afastadas (sumô)');
insert into public.exercicios (nome, instrucoes, series_padrao, reps_padrao, fotos, ativo) select 'Afundo para trás (avanço reverso)', 'Em pé, dê um passo para trás e desça dobrando os dois joelhos até o joelho de trás quase tocar o chão. Volte empurrando com a perna da frente. Cuidado: tronco reto; o joelho da frente fica sobre o tornozelo.', 2, '8 por lado', array['fotos-exercicios/desenho-avanco-reverso-1.webp','fotos-exercicios/desenho-avanco-reverso-2.webp']::text[], true where not exists (select 1 from public.exercicios where nome = 'Afundo para trás (avanço reverso)');
insert into public.exercicios (nome, instrucoes, series_padrao, reps_padrao, fotos, ativo) select 'Mobilidade de tornozelo na parede', 'Semiajoelhado de frente para a parede, com o pé da frente a um palmo dela. Leve o joelho em direção à parede sem tirar o calcanhar do chão e volte. Cuidado: o joelho vai na direção do dedão.', 2, '10 por lado', array['fotos-exercicios/desenho-mobilidade-tornozelo-1.webp','fotos-exercicios/desenho-mobilidade-tornozelo-2.webp']::text[], true where not exists (select 1 from public.exercicios where nome = 'Mobilidade de tornozelo na parede');
insert into public.exercicios (nome, instrucoes, series_padrao, reps_padrao, fotos, ativo) select 'Elevação de pelve lateral no degrau', 'Em pé de lado num degrau, apoiado só numa perna e com a outra solta para fora. Deixe a pelve do lado solto descer um pouco e suba usando o quadril da perna de apoio. Cuidado: joelho de apoio esticado; segure num corrimão.', 2, '10 por lado', array['fotos-exercicios/desenho-elevacao-pelve-degrau-1.webp','fotos-exercicios/desenho-elevacao-pelve-degrau-2.webp']::text[], true where not exists (select 1 from public.exercicios where nome = 'Elevação de pelve lateral no degrau');
insert into public.exercicios (nome, instrucoes, series_padrao, reps_padrao, fotos, ativo) select 'Respiração 90/90 com pés na parede', 'Deite com os pés apoiados na parede, quadril e joelhos dobrados a 90 graus. Puxe o ar pelo nariz enchendo a barriga e solte o ar devagar, sentindo a lombar encostar no chão. Cuidado: os ombros ficam relaxados.', 2, '8 respirações', array['fotos-exercicios/desenho-respiracao-90-90-1.webp','fotos-exercicios/desenho-respiracao-90-90-2.webp']::text[], true where not exists (select 1 from public.exercicios where nome = 'Respiração 90/90 com pés na parede');
insert into public.exercicios (nome, instrucoes, series_padrao, reps_padrao, fotos, ativo) select 'Crescimento axial em pé (alongar a coluna)', 'Em pé, imagine um fio puxando o topo da cabeça para cima. Cresça alongando a coluna, sem tirar os calcanhares do chão, segure 5 segundos e solte. Cuidado: ombros relaxados e respiração normal.', 1, '8 (segure 5 s)', array['fotos-exercicios/desenho-crescimento-axial-1.webp','fotos-exercicios/desenho-crescimento-axial-2.webp']::text[], true where not exists (select 1 from public.exercicios where nome = 'Crescimento axial em pé (alongar a coluna)');
insert into public.exercicios (nome, instrucoes, series_padrao, reps_padrao, fotos, ativo) select 'Gato e camelo sentado', 'Sentado na ponta da cadeira, mãos nos joelhos. Arredonde as costas olhando para o umbigo e depois estufe o peito olhando para a frente. Movimento lento, acompanhando a respiração. Cuidado: sem dor; amplitude confortável.', 2, '10', array['fotos-exercicios/desenho-gato-camelo-sentado-1.webp','fotos-exercicios/desenho-gato-camelo-sentado-2.webp']::text[], true where not exists (select 1 from public.exercicios where nome = 'Gato e camelo sentado');
